With notation as in
Lemma \ref{lemma-enough-injectives}
we have $R^pQ(F) = 0$ for all $p > 0$ and any adequate functor $F$.

\begin{reference}
This is a special case of \cite[Satz 2]{Faltings-finiteness}.
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Set $Z = V(I) \subset \Spec(A)$. Let $M$ be a finite $A$-module.
Set $s = s_{A, I}(M)$ as in (\ref{equation-cutoff}).
Assume that
\begin{enumerate}
\item $A$ is universally catenary,
\item the formal fibres of the local rings of $A$ are Cohen-Macaulay.
\end{enumerate}
Then $H^i_Z(M)$ is finite for $0 \leq i < s$ and
$H^s_Z(M)$ is not finite.

With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
for $a \geq 0$ we have
\begin{enumerate}
\item the map
$\Omega^a_{X/S} \to b_*\Omega^a_{X'/S}$ is an isomorphism,
\item the map $\Omega^a_{Z/S} \to p_*\Omega^a_{E/S}$ is an isomorphism,
\item the map $Rb_*\Omega^a_{X'/S} \to i_*Rp_*\Omega^a_{E/S}$ is an isomorphism
on cohomology sheaves in degree $\geq 1$.
\end{enumerate}

Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $x \in |\mathcal{X}|$. Consider commutative diagrams
$$
\vcenter{
\xymatrix{
U \ar[d]_a \ar[r]_h & V \ar[d]^b \\
\mathcal{X} \ar[r]^f & \mathcal{Y}
}
}
\quad\text{with points}
\vcenter{
\xymatrix{
u \in |U| \ar[d] \\
x \in |\mathcal{X}|
}
}
$$
where $U$ and $V$ are algebraic spaces, $b$ is flat, and
$(a, h) : U \to \mathcal{X} \times_\mathcal{Y} V$
is flat. The following are equivalent
\begin{enumerate}
\item $h$ is flat at $u$ for one diagram as above,
\item $h$ is flat at $u$ for every diagram as above.
\end{enumerate}

With notation as in (\ref{equation-three-maps}) set
$$
\begin{matrix}
\Omega_1 = \Omega_{\mathcal{O}/A} \otimes_\mathcal{O} \underline{B}
\text{ on }\mathcal{C}_{B/A} \\
\Omega_2 = \Omega_{\mathcal{O}/A} \otimes_\mathcal{O} \underline{C}
\text{ on }\mathcal{C}_{C/A} \\
\Omega_3 = \Omega_{\mathcal{O}/B} \otimes_\mathcal{O} \underline{C}
\text{ on }\mathcal{C}_{C/B}
\end{matrix}
$$
Then we have a canonical short exact sequence of sheaves
of $\underline{C}$-modules
$$
0 \to g_1^{-1}\Omega_1 \otimes_{\underline{B}} \underline{C} \to
g_2^{-1}\Omega_2 \to
g_3^{-1}\Omega_3 \to 0
$$
on $\mathcal{C}_{C/B/A}$.

In Situation \ref{situation-loc-chern}
if $\alpha \in \CH_k(X)$ has support disjoint from $Z$, then
$P_p(Z \to X, E) \cap \alpha = 0$, resp.\ $c_p(Z \to X, E) \cap \alpha = 0$.

Let $B \to S$ be as in Section \ref{section-notation}.
Let $(U, R, s, t, c)$ be a groupoid in algebraic spaces over $B$.
Let $G \to U$ be the stabilizer group algebraic space.
\begin{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_B U$ is separated,
\item $G \to U$ is separated, and
\item $e : U \to G$ is a closed immersion.
\end{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_B U$ is locally separated,
\item $G \to U$ is locally separated, and
\item $e : U \to G$ is an immersion.
\end{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_B U$ is quasi-separated,
\item $G \to U$ is quasi-separated, and
\item $e : U \to G$ is quasi-compact.
\end{enumerate}
\end{enumerate}

Assumptions and notation as in
Lemmas \ref{lemma-quotient-stack-arrows} and
\ref{lemma-quotient-stack-2-arrow}.
The vertical composition of
$$
\xymatrix@C=15pc{
\mathcal{S}_{R \times_{s, U, t} R}
\ruppertwocell^{\pi \circ s \circ \text{pr}_1 = \pi \circ s \circ c}{\ \ \ \ \ \ \alpha \star \text{id}_{\text{pr}_1}}
\ar[r]_(.3){\pi \circ t \circ \text{pr}_1 = \pi \circ s \circ \text{pr}_0}
\rlowertwocell_{\pi \circ t \circ \text{pr}_0 = \pi \circ t \circ c}{\ \ \ \ \ \ \alpha \star \text{id}_{\text{pr}_0}}
&
[U/R]
}
$$
is the $2$-morphism $\alpha \star \text{id}_c$. In a formula
$\alpha \star \text{id}_c =
(\alpha \star \text{id}_{\text{pr}_0})
\circ
(\alpha \star \text{id}_{\text{pr}_1})
$.

With $A$, $B$, $F$, and $F'$ as in Lemma \ref{lemma-functor-fp-modules}.
\begin{enumerate}
\item If $F$ is additive, then $F'$ is additive and
commutes with arbitrary direct sums, and
\item if $F$ is right exact, then $F'$ is right exact.
\end{enumerate}

\begin{reference}
Compare with \cite[Definition 7.2.4]{BS}.
\end{reference}
Let $(\mathcal{C}, F)$ be a Galois category. Let $G = \text{Aut}(F)$
be as in Example \ref{example-from-C-F-to-G-sets}. For any connected
$X$ in $\mathcal{C}$ the action of $G$ on $F(X)$ is transitive.

In the situation above the following are equivalent
\begin{enumerate}
\item $X$ is unramified in $L$,
\item $Y \to X$ is \'etale, and
\item $Y \to X$ is finite \'etale.
\end{enumerate}

local_context_used.source_statement:
Let $S$ be a scheme. Consider a separated \'etale morphism
$f : V \to W$ of algebraic spaces over $S$.
Assume there exists a
closed subspace $T \subset W$ such that $f^{-1}T \to T$ is
an isomorphism. Then, with $W^0 = W \setminus T$ and
$V^0 = f^{-1}W^0$ the base change functor
$$
\left\{
\begin{matrix}
g : X \to W\text{ morphism of algebraic spaces} \\
g^{-1}(W^0) \to W^0\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
h : Y \to V\text{ morphism of algebraic spaces} \\
h^{-1}(V^0) \to V^0\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

