With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
the map $\Omega^\bullet_{X/S} \to Rb_*\Omega^\bullet_{X'/S}$
has a splitting in $D(X, (X \to S)^{-1}\mathcal{O}_S)$.

In the situation above the following diagram commutes
$$
\xymatrix{
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
f_*\mathcal{M}^\bullet \ar[r] \ar[d]
&
Rf_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
Rf_*\mathcal{M}^\bullet \ar[d]^{\text{Remark \ref{remark-cup-product}}} \\
\text{Tot}(
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
f_*\mathcal{M}^\bullet) \ar[d]_{\text{naive cup product}} &
Rf_*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
\mathcal{M}^\bullet) \ar[d] \\
f_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}
\mathcal{M}^\bullet) \ar[r] &
Rf_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}
\mathcal{M}^\bullet)
}
$$

Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item With $g$ as in Lemma \ref{lemma-lisse-etale}
for the lisse-\'etale site we have
\begin{enumerate}
\item the functors $g^{-1}$ and $g_!$ define mutually inverse functors
$$
\xymatrix{
\QCoh(\mathcal{O}_\mathcal{X}) \ar@<1ex>[r]^-{g^{-1}} &
\QCoh(\mathcal{X}_{lisse,\etale},
\mathcal{O}_{\mathcal{X}_{lisse,\etale}}) \ar@<1ex>[l]^-{g_!}
}
$$
\item if $\mathcal{F}$ is in $\textit{LQCoh}^{fbc}(\mathcal{O}_\mathcal{X})$
then $g^{-1}\mathcal{F}$ is in
$\QCoh(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$ and
\item $Q(\mathcal{F}) = g_!g^{-1}\mathcal{F}$ where $Q$ is as in
Lemma \ref{lemma-adjoint}.
\end{enumerate}
\item With $g$ as in Lemma \ref{lemma-lisse-etale}
for the flat-fppf site we have
\begin{enumerate}
\item the functors $g^{-1}$ and $g_!$ define mutually inverse functors
$$
\xymatrix{
\QCoh(\mathcal{O}_\mathcal{X}) \ar@<1ex>[r]^-{g^{-1}} &
\QCoh(\mathcal{X}_{flat,fppf},
\mathcal{O}_{\mathcal{X}_{flat,fppf}}) \ar@<1ex>[l]^-{g_!}
}
$$
\item if $\mathcal{F}$ is in $\textit{LQCoh}^{fbc}(\mathcal{O}_\mathcal{X})$
then $g^{-1}\mathcal{F}$ is in
$\QCoh(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$
and
\item $Q(\mathcal{F}) = g_!g^{-1}\mathcal{F}$ where $Q$ is as in
Lemma \ref{lemma-adjoint}.
\end{enumerate}
\end{enumerate}

In the situation above there is a functor
$$
\begin{matrix}
\text{crystals in quasi-coherent} \\
\mathcal{O}_{X/S}\text{-modules on }\text{Cris}(X/S)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{pairs }(M, \nabla)\text{ satisfying} \\
\text{(\ref{item-complete}), (\ref{item-connection}),
(\ref{item-integrable}), and (\ref{item-topologically-quasi-nilpotent})}
\end{matrix}
$$

Let $\mathcal{F}$ be a presheaf on $(\Sch/S)_{ph}$.
Then $\mathcal{F}$ is a sheaf if and only if
\begin{enumerate}
\item $\mathcal{F}$ satisfies the sheaf condition for
Zariski coverings, and
\item if $f : V \to U$ is proper surjective, then
$\mathcal{F}(U)$ maps bijectively to the equalizer
of the two maps $\mathcal{F}(V) \to \mathcal{F}(V \times_U V)$.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to property
\begin{enumerate}
\item[(2')] the sheaf property for $\{V \to U\}$ as in (2) with $U$ affine.
\end{enumerate}

In Semistable Reduction, Situation \ref{models-situation-regular-model}
the dualizing module of $C_i$ over $k$ is
$$
\omega_{C_i} = \omega_X(C_i)|_{C_i}
$$
where $\omega_X$ is as above.

In the situation of Example \ref{example-family-associated-closed}
assume $S$ is locally Noetherian and $Z$ is flat over $S$ in dimensions
$\geq r$. Then $[Z/X/S]_r$ is a relative $r$-cycle on $X/S$.

\begin{reference}
\cite[III Proposition 2.1.12]{EGA}
\end{reference}
Let $R$ be a ring.
Let $n \geq 0$ be an integer.
We have
$$
H^q(\mathbf{P}^n, \mathcal{O}_{\mathbf{P}^n_R}(d)) =
\left\{
\begin{matrix}
(R[T_0, \ldots, T_n])_d & \text{if} & q = 0,\ d \geq 0 \\
\left(\frac{1}{T_0 \ldots T_n} R[\frac{1}{T_0}, \ldots, \frac{1}{T_n}]\right)_d
& \text{if} & q = n,\ d < 0 \\
0 & \text{if} & q, n, d\text{ not as above}
\end{matrix}
\right.
$$
as $R$-modules.

In Situation \ref{situation-setup-base-change} let $Y \to X \to S$ be locally
of finite type and let $Y' \to X' \to S'$ be the base change by $S' \to S$.
Assume $f : Y \to X$ is flat of relative dimension $r$. Then $f' : Y' \to X'$
is flat of relative dimension $r$ and the diagrams
$$
\vcenter{
\xymatrix{
Z_{k + r}(Y) \ar[r]_{g^*} & Z_{k + c + r}(Y') \\
Z_k(X) \ar[r]^{g^*} \ar[u]^{f^*} & Z_{k + c}(X') \ar[u]_{(f')^*}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\CH_{k + r}(Y) \ar[r]_{g^*} & \CH_{k + c + r}(Y') \\
\CH_k(X) \ar[r]^{g^*} \ar[u]^{f^*} & \CH_{k + c}(X') \ar[u]_{(f')^*}
}
}
$$
of cycle and chow groups commutes.

With $S$, $\varphi : U \to X$, and $(U, R, s, t, c)$ as above.
For any quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ the
sheaf $\varphi^*\mathcal{F}$ comes equipped with a canonical
isomorphism
$$
\alpha : t^*\varphi^*\mathcal{F} \longrightarrow s^*\varphi^*\mathcal{F}
$$
which satisfies the conditions of
Groupoids, Definition \ref{groupoids-definition-groupoid-module}
and therefore defines a quasi-coherent sheaf on $(U, R, s, t, c)$.
The functor $\mathcal{F} \mapsto (\varphi^*\mathcal{F}, \alpha)$
defines an equivalence of categories
$$
\begin{matrix}
\text{Quasi-coherent} \\
\mathcal{O}_X\text{-modules}
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{Quasi-coherent modules}\\
\text{on }(U, R, s, t, c)
\end{matrix}
$$

With $k$, $n$, and $R$ as above, for an object $K$ of $D(R)$
the following are equivalent
\begin{enumerate}
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(K) < \infty$, and
\item $K$ is a compact object.
\end{enumerate}

Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p :
\mathcal{G}/\mathcal{B}\textit{-Torsors}
\longrightarrow
(\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

In the situation above the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through the open where $\Curvesstack \to \Spec(\mathbf{Z})$ is smooth,
\item the deformation category $\Deformationcategory_X$ is unobstructed.
\end{enumerate}

With notation as above we have
\begin{enumerate}
\item $\Omega^p_{L^\star/S, n} =
\Omega^p_{L^\star/S, 0} \otimes_{\mathcal{O}_X} \mathcal{L}^{\otimes n}$
for all $n \in \mathbf{Z}$ as quasi-coherent $\mathcal{O}_X$-modules,
\item $\Omega^\bullet_{X/S} = \Omega^\bullet_{L/X, 0}$
as complexes, and
\item for $n > 0$ and $p \geq 0$ we have
$\Omega^p_{L/X, n} = \Omega^p_{L^\star/S, n}$.
\end{enumerate}

Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module
with the flat base change property on $\mathcal{X}_\etale$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g : \Sh(\mathcal{X}_{lisse,\etale}) \to
\Sh(\mathcal{X}_\etale)$ is as in Lemma \ref{lemma-lisse-etale}.
\end{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module on
$\mathcal{X}_{fppf}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g :  \Sh(\mathcal{X}_{flat,fppf}) \to \Sh(\mathcal{X}_{fppf})$
is as in Lemma \ref{lemma-lisse-etale}.
\end{enumerate}
\end{enumerate}

Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
With $a_X : \Sh((\textit{Spaces}/X)_{fppf}) \to \Sh(X_\etale)$
as above:
\begin{enumerate}
\item $H^q(X_\etale, \mathcal{F}) = H^q_{fppf}(X, a_X^{-1}\mathcal{F})$
for an abelian sheaf $\mathcal{F}$ on $X_\etale$,
\item $H^q(X_\etale, K) = H^q_{fppf}(X, a_X^{-1}K)$ for $K \in D^+(X_\etale)$.
\end{enumerate}
Example: if $A$ is an abelian group, then
$H^q_\etale(X, \underline{A}) = H^q_{fppf}(X, \underline{A})$.

In Situation \ref{situation-setup-base-change} let $Y \to X \to S$ be locally
of finite type and let $Y' \to X' \to S'$ be the base change by $S' \to S$.
Assume $f : Y \to X$ is proper. Then $f' : Y' \to X'$ is proper and the diagram
$$
\vcenter{
\xymatrix{
Z_k(Y) \ar[r]_{g^*} \ar[d]_{f_*} & Z_{k + c}(Y') \ar[d]^{f'_*} \\
Z_k(X) \ar[r]^{g^*} & Z_{k + c}(X')
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\CH_k(Y) \ar[r]_{g^*} \ar[d]_{f_*} & \CH_{k + c}(Y') \ar[d]^{f'_*} \\
\CH_k(X) \ar[r]^{g^*} & \CH_{k + c}(X')
}
}
$$
of cycle and chow groups commutes.

\begin{reference}
\cite[Theorem 6.8]{Rouquier-dimensions}
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme. Let $T \subset X$ be a
closed subset such that $X \setminus T$ is quasi-compact. With notation
as above, the category $D_{\QCoh, T}(\mathcal{O}_X)$ is generated by a
single perfect object.

With notation as in Example \ref{example-decompose-P1}
\begin{enumerate}
\item
the motive $(X, c_0, 0)$ is isomorphic to the motive
$\mathbf{1} = (\Spec(k), 1, 0)$.
\item
the motive $(X, c_2, 0)$ is isomorphic to the motive
$\mathbf{1}(-1) = (\Spec(k), 1, -1)$.
\end{enumerate}

In Situation \ref{situation-regular-model} the symmetric bilinear form
(\ref{equation-form}) has the following properties
\begin{enumerate}
\item $(C_i \cdot C_j) \geq 0$ if $i \not = j$ with equality if and only
if $C_i \cap C_j = \emptyset$,
\item $(\sum m_i C_i \cdot C_j) = 0$,
\item there is no nonempty proper subset $I \subset \{1, \ldots, n\}$
such that $(C_i \cdot C_j) = 0$ for $i \in I$, $j \not \in I$.
\item $(\sum a_i C_i \cdot \sum a_i C_i) \leq 0$ with equality if and
only if there exists a $q \in \mathbf{Q}$ such that $a_i = qm_i$
for $i = 1, \ldots, n$,
\end{enumerate}

In Situation \ref{situation-free-at-generic-points}.
\begin{enumerate}
\item The functor $H_p$ satisfies the sheaf property for the fpqc topology.
\item If $\mathcal{F}$ is of finite presentation, then functor $H_p$ is
limit preserving.
\end{enumerate}
